def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.166.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.165.0"' not in init:
        sys.exit("ABORT: not at v3.165.0.")
    for k in ("sysadmin_function", "users_permissions"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("SYS1", LESSONS_S1, QUESTIONS_S1, 9) + _validate("SYS2", LESSONS_S2, QUESTIONS_S2, 10)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("SYS 1", LESSONS_S1, QUESTIONS_S1, "sysadmin_function",
         "The sysadmin function on the managed CloudERP.One platform: the custody map (site, apps, Desk, bench); the awesome bar; DocType grammar and the docstatus lifecycle; lists, saved filters, and the three report kinds; the System Settings walk with its three rules; workspace curation per job family with the click-count audit; the sysadmin calendar by frequency; and the five-item support report."),
        ("SYS 2", LESSONS_S2, QUESTIONS_S2, "users_permissions",
         "Users, roles, and permissions in ZhiftERP: the User record and the System/Website User distinction; the joiner, mover, and leaver procedures — leavers disabled, never deleted; Role Profiles as jobs-as-objects with the two-System-Manager rule; the Role Permission Manager's actions, If Owner, and permission levels; User Permissions as record-level fences with Applicable For; share, assignment, and workflow kept distinct from permission; and the weekly delta, monthly permission delta, and quarterly access recertification."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.165.0"', '"3.166.0"'))
    print("  data: SYSADMIN 1 + 2 lessons + banks REPLACED (style v3, product-first)")
    print("wrote __version__ -> 3.166.0")


if __name__ == "__main__":
    main()
